INSERT INTO public.preguntas
  ("año", numero, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema, explicacion_calidad)
VALUES
  (2022, 1, 'Saquinavir y ritonavir son fármacos utilizados en el tratamiento del SIDA que son además un ejemplo de diseño racional basado en la estructura. ¿Cuál de las siguientes afirmaciones describe correctamente a estos compuestos?:', 'Son peptidomiméticos diseñados para inhibir la proteasa del VIH y actuar como análogos del estado de transición.', 'Son análogos de los ácidos nucleicos y actúan como inhibidores competitivos de la transcriptasa inversa.', 'Son peptidomiméticos diseñados para inhibir la integrasa del VIH y actuar como inhibidores reversibles.', 'Son compuestos que contienen en su estructura un sistema de didesoxiribosa, diseñados para actuar como inhibidores de una proteasa del VIH.', NULL, 'a', NULL, NULL, NULL),
  (2022, 2, 'Las penicilinas poseen una estructura bicíclica que contiene una β-lactama fundamental para su actividad antibacteriana. Este sistema bicíclico:', 'Confiere una elevada tensión que dificulta su apertura por las β-lactamasas bacterianas, confiriéndole así resistencia a estas enzimas.', 'Mimetiza el enlace glicosídico entre N-acetilmurámico y N-acetilglucosamina impidiendo así la síntesis del peptidoglicano presente en la pared celular bacteriana.', 'Mimetiza el dímero de D-Ala-D-Ala presente en el peptidoglicano, inhibiendo irreversiblemente la transpeptidasa.', 'Puede ser modificado bioisostéricamente, sustituyendo el nitrógeno por un oxígeno y dando lugar a una β-lactona química y enzimáticamente más estable.', NULL, 'c', NULL, NULL, NULL),
  (2022, 3, 'Los β-bloqueantes fueron diseñados para actuar como antagonistas de los receptores β-1 del corazón. Estructuralmente son ariloxipropanolaminas y su selectividad cardiaca se consigue:', 'Introduciendo un grupo pequeño (H, metilo) en el grupo amino.', 'Introduciendo un grupo moderadamente voluminoso (isopropilo) en el grupo amino.', 'Eliminando el grupo catecol y sustituyéndolo por un arilo más voluminoso.', 'Epimerizando el grupo hidroxilo.', NULL, 'b', NULL, NULL, NULL),
  (2022, 4, 'El sistema de quinolina forma parte de la estructura de muchos fármacos. Su síntesis se puede llevar a cabo mediante el método de Skraup, que implica hacer reaccionar derivados de:', 'Anilina con ácido sulfúrico y glicerina en presencia de nitrobenceno.', 'Piridina con malonato de dietilo en medio básico.', 'Fenilpropilamina en condiciones de ciclación.', 'Anilina con propanol en condiciones de sustitución nucleófila aromática.', NULL, 'a', NULL, NULL, NULL),
  (2022, 5, '¿Cuál de los siguientes antagonistas de los canales NMDA del ácido glutámico es además un agente antiviral?:', 'Ketamina.', 'Amantadina.', 'Ganciclovir.', 'Dextrometorfano.', NULL, 'b', NULL, NULL, NULL),
  (2022, 6, '¿Con qué nombre se describen los fármacos que mantienen la actividad opioide de la morfina y carecen del anillo de epóxido y del anillo C de esta?:', 'Morfinanos.', 'Fenilpiperidinas.', 'Anilinopiperidinas.', 'Benzomorfanos.', NULL, 'd', NULL, NULL, NULL),
  (2022, 7, 'En el diseño de las estatinas, ¿qué fragmento de la estructura se considera esencial para realizar la actividad inhibidora del enzima HMG-CoA reductasa?:', 'El fragmento de decalina.', 'El fragmento de β-hidroxi-δ-lactona o su correspondiente dihidroxiácido.', 'El anillo aromático halogenado.', 'El grupo isopropilo.', NULL, 'b', NULL, NULL, NULL),
  (2022, 8, '¿Cuál de las siguientes ecuaciones define al coeficiente de partición (P) de un fármaco, siendo [fármaco] la concentración de dicho fármaco en el disolvente indicado?:', 'P = [fármaco]agua /[fármaco]octanol.', 'P = Log[fármaco]agua.', 'P = [fármaco]octanol /[fármaco]agua.', 'P = Log[fármaco]octanol.', NULL, 'c', NULL, NULL, NULL),
  (2022, 9, '¿Qué tipo de intermedio reactivo se forma en el metabolismo oxidativo de los anillos aromáticos y es responsable de su toxicidad?:', 'Quinona.', '1,2-Diol.', 'Epóxido.', 'Radical hidroxilo.', NULL, 'c', NULL, NULL, NULL),
  (2022, 10, 'La metodología utilizada para preparar, en un proceso único y eficiente, una mezcla o colección de compuestos estructuralmente relacionados, se denomina:', 'Química supramolecular.', 'Química combinatoria.', 'Química divergente.', 'Química sostenible.', NULL, 'b', NULL, NULL, NULL),
  (2022, 11, '¿Cuál es el papel fundamental del grupo metoxilo en la posición 4 del anillo de piridina del omeprazol?:', 'Aumentar su estabilidad metabólica.', 'Disminuir su lipofilia para disminuir su absorción.', 'Aumentar la nucleofilia del nitrógeno piridínico para su bioactivación.', 'Aumentar su lipofilia para favorecer su absorción.', NULL, 'c', NULL, NULL, NULL),
  (2022, 12, 'El atracurio es un bloqueante neuromuscular análogo sintético de la tubocurarina que se inactiva rápidamente en la sangre (pH= 7,4) por una reacción de:', 'Hidrólisis de un grupo carbamato.', 'Desmetilación de la sal de amonio cuaternario.', 'Oxidación del heterociclo nitrogenado.', 'Eliminación de Hofmann.', NULL, 'd', NULL, NULL, NULL),
  (2022, 13, '¿Cuáles de los siguientes fragmentos deben estar presentes en la estructura de los antagonistas nicotínicos?:', 'Dos restos de acetilcolina situados a una determinada distancia el uno del otro.', 'Un átomo de nitrógeno cuaternario, una función oxigenada, y dos grupos apolares próximos a esta última.', 'Dos átomos de nitrógeno cargados unidos por un espaciador, de manera que estén situados a una distancia determinada el uno del otro.', 'Un nitrógeno cuaternario y anillos aromáticos con grupos aceptores de electrones.', NULL, 'c', NULL, NULL, NULL),
  (2022, 14, '¿Qué consecuencia tiene la introducción de un grupo etinilo en la posición 17-α del estradiol?:', 'Aumenta la selectividad al facilitar la unión al receptor α y al impedir la interacción con el receptor β.', 'Prolonga la actividad del fármaco por inhibición de su metabolismo.', 'Aumenta la unión al receptor al incrementar la acidez del grupo OH en la posición 17-β.', 'Cambia la actividad del fármaco de agonista a antagonista.', NULL, 'b', NULL, NULL, NULL),
  (2022, 15, '¿Qué parte de la estructura de la eritromicina es responsable de su inestabilidad química?:', 'El fragmento de β-hidroxicarbonilo.', 'El resto de aminoazúcar.', 'El grupo lactona.', 'Los dos fragmentos de γ-hidroxicarbonilo.', NULL, 'd', NULL, NULL, NULL),
  (2022, 16, 'Las oripavinas son análogos rígidos de la morfina. Se obtienen a partir del alcaloide tebaína, aprovechando la presencia en su estructura de un sistema de dos dobles enlaces conjugados, por medio de la siguiente reacción:', 'Cicloadición [4+2].', 'Expansión de anillo.', 'Cicloadición [3+2].', 'Contracción de anillo.', NULL, 'a', NULL, NULL, NULL),
  (2022, 17, 'En el diseño de fármacos, la sustitución de una función éster por un grupo carbamato, ¿qué consecuencia tiene?:', 'Un aumento de la lipofilia y, por tanto, mejor absorción.', 'Una disminución de la vida media.', 'Un aumento de la estabilidad metabólica.', 'Un incremento del impedimento estérico.', NULL, 'c', NULL, NULL, NULL),
  (2022, 18, '¿Qué característica estructural es común en los agentes intercalantes del ADN?:', 'Una cadena peptídica.', 'Un anillo de aziridina.', 'Un sistema plano de anillos aromáticos o heteroaromáticos.', 'Un fragmento de β-hidroxicarbonilo.', NULL, 'c', NULL, NULL, NULL),
  (2022, 19, '¿Cuál es la respuesta correcta respecto al microorganismo Hafnia alvei?:', 'Es una enterobacteria.', 'Es un bacilo gramnegativo no fermentador.', 'Es una espiroqueta.', 'Es una bacteria intracelular.', NULL, 'a', NULL, NULL, NULL),
  (2022, 20, '¿Cuál es la respuesta INCORRECTA respecto al virus de la parotiditis?:', 'Pertenece a la familia Paramyxoviridae.', 'El único hospedador es el ser humano.', 'Puede producir epidídimo-orquitis.', 'Es un virus ARN monocatenario con simetría icosaédrica.', NULL, 'd', NULL, NULL, NULL),
  (2022, 21, '¿Cuál de las siguientes respuestas es correcta respecto al virus SARS-CoV-2?:', 'Es un virus ARN bicatenario de simetría helicoidal.', 'Reconoce el receptor humano ACE2 (enzima convertidora de angiotensina 2).', 'El gen estructural S es idéntico al del virus SARS-CoV-1.', 'Pertenece a la familia Orthomyxoviridae.', NULL, 'b', NULL, NULL, NULL),
  (2022, 22, '¿Por qué es difícil el aislamiento microbiológico de Francisella tularensis?:', 'Solo crece en anaerobiosis tras una incubación prolongada.', 'Necesita medios de cultivo enriquecidos con cisteína y una incubación prolongada.', 'Necesita medios de cultivo enriquecidos con carbón vegetal y una incubación prolongada.', 'Necesita sistemas de cultivo celulares y una incubación prolongada.', NULL, 'b', NULL, NULL, NULL),
  (2022, 23, '¿Cuál de las siguientes afirmaciones es INCORRECTA respecto al género Bartonella?:', 'Son pequeños cocobacilos o bacilos gramnegativos con requerimientos de crecimiento exigentes.', 'Bartonella bacilliformis es responsable de la enfermedad de Carrión.', 'Bartonella quintana se transmite de persona a persona a través de los piojos.', 'Bartonella henselae se transmite a través de las moscas de la arena.', NULL, 'd', NULL, NULL, NULL),
  (2022, 24, 'Señale cuál de las siguientes afirmaciones sobre Campylobacter jejuni es INCORRECTA:', 'Es un bacilo gramnegativo curvo.', 'Gran parte de las infecciones que produce están relacionadas con el consumo de pollo.', 'Para su aislamiento a partir de heces se requiere la incubación con atmósfera de microaerofilia.', 'Es resistente a los macrólidos.', NULL, 'd', NULL, NULL, NULL),
  (2022, 25, '¿Cuál de los siguientes microorganismos es grampositivo?:', 'Listeria monocytogenes.', 'Bordetella pertussis.', 'Francisella tularensis.', 'Helicobacter pylori.', NULL, 'a', NULL, NULL, NULL),
  (2022, 26, 'Señale la respuesta correcta sobre el género Mycobacterium:', 'Mycobacterium chelonae es una micobacteria de crecimiento lento.', 'Mycobacterium kansasii es una micobacteria no cromógena.', 'Mycobacterium tuberculosis da positiva la prueba de niacina.', 'Mycobacterium bovis es sensible a pirazinamida.', NULL, 'c', NULL, NULL, NULL),
  (2022, 27, 'Las micosis sistémicas endémicas son aquellas causadas por:', 'Dermatofitos.', 'Hongos dimórficos.', 'Mucorales.', 'Hongos hialinos.', NULL, 'b', NULL, NULL, NULL),
  (2022, 28, 'Señale cuál de los siguientes microorganismos presenta resistencia intrínseca de bajo nivel a vancomicina:', 'Enterococcus casseliflavus.', 'Abiotrophia defectiva.', 'Streptococcus gallolyticus.', 'Gemella haemolysans.', NULL, 'a', NULL, NULL, NULL),
  (2022, 29, 'En el cultivo de un aspirado bronquial, tras 24 horas de incubación a 37 ºC, se observa crecimiento en agar MacConkey. Las colonias son oxidasa positiva y presentan pigmento verde. ¿Cuál sería la identificación presuntiva?:', 'Staphylococcus aureus.', 'Escherichia coli.', 'Pseudomonas aeruginosa.', 'Acinetobacter baumannii.', NULL, 'c', NULL, NULL, NULL),
  (2022, 30, '¿Qué microorganismo es el principal agente causal de infección de tracto urinario en población general?:', 'Staphylococcus saprophyticus.', 'Escherichia coli.', 'Pseudomonas aeruginosa.', 'Proteus mirabilis.', NULL, 'b', NULL, NULL, NULL),
  (2022, 31, '¿Cuál de los siguientes fármacos NO se utiliza en el tratamiento de la tuberculosis?:', 'Amikacina.', 'Bedaquilina.', 'Vancomicina.', 'Isoniazida.', NULL, 'c', NULL, NULL, NULL),
  (2022, 32, 'Señale la relación INCORRECTA entre antibiótico y mecanismo de acción:', 'Ciprofloxacino – inhibición de la síntesis de la pared bacteriana.', 'Colistina – acción sobre el lipopolisacárido de la membrana bacteriana.', 'Vancomicina – bloqueo de la transglucosilación en la síntesis del peptidoglicano.', 'Gentamicina – alteración de la síntesis proteica.', NULL, 'a', NULL, NULL, NULL),
  (2022, 33, '¿Cuál de los siguientes antibióticos NO es activo frente a bacterias grampositivas?:', 'Daptomicina.', 'Linezolid.', 'Dalbavancina.', 'Colistina.', NULL, 'd', NULL, NULL, NULL),
  (2022, 34, 'En la tinción de Gram de un exudado uretral se observan diplococos gramnegativos intracelulares y un predominio de leucocitos polimorfonucleares. ¿Qué microorganismo cuenta con un alto grado de sospecha?:', 'Mycoplasma genitalium.', 'Chlamydia trachomatis.', 'Neisseria gonorrhoeae.', 'Haemophilus ducreyi.', NULL, 'c', NULL, NULL, NULL),
  (2022, 35, '¿Cuál de los siguientes antibióticos sería adecuado para tratar una infección causada por Klebsiella pneumoniae productora de βlactamasa de espectro extendido (BLEE)?:', 'Ertapenem.', 'Amoxicilina.', 'Cefotaxima.', 'Aztreonam.', NULL, 'a', NULL, NULL, NULL),
  (2022, 36, '¿Cuál de las siguientes NO es una forma de tularemia?:', 'Enfermedad pulmonar.', 'Enfermedad ulceroglandular.', 'Enfermedad oculoganglionar.', 'Enfermedad de Brill-Zinsser.', NULL, 'd', NULL, NULL, NULL),
  (2022, 37, '¿Cuál de los siguientes microorganismos es un patógeno humano estricto?:', 'Shigella dysenteriae.', 'Yersinia pestis.', 'Campylobacter jejuni.', 'Francisella tularensis.', NULL, 'a', NULL, NULL, NULL),
  (2022, 38, '¿Qué parásito se distribuye mayoritariamente en Estados Unidos?:', 'Babesia microti.', 'Clonorchis sinensis.', 'Diphyllobothrium latum.', 'Acanthotrema felis.', NULL, 'a', NULL, NULL, NULL),
  (2022, 39, '¿Qué afirmación es cierta en relación al ciclo biológico de Trichuris trichura?:', 'Los huevos embrionados se excretan en las heces.', 'Después de la ingesta, los huevos eclosionan en el intestino grueso.', 'Las larvas maduran en adultos y se establecen en el intestino delgado.', 'Los gusanos adultos viven en el ciego.', NULL, 'd', NULL, NULL, NULL),
  (2022, 40, 'Una niña de 5 años natural de Ecuador presenta epigastralgias, falta de apetito, y déficit de desarrollo corporal. En el examen parasitológico de las heces se observa la presencia de un huevo ovalado de 45 x 38 µm, que contiene un embrión hexacanto y 4 filamentos polares entre las dos membranas. ¿A qué parásito corresponde la descripción?:', 'Taenia saginata.', 'Hymenolepis nana.', 'Hymenolepis diminuta.', 'Dipylidium caninum.', NULL, 'b', NULL, NULL, NULL),
  (2022, 41, 'El planteamiento matemático de Arrhenius dentro del campo del desarrollo farmacéutico sirve para estimar:', 'La velocidad de degradación de un fármaco a diferentes temperaturas a partir de la temperatura cinética media.', 'La solubilidad real de un fármaco a partir de su solubilidad ideal, según los valores de entalpía de disolución.', 'La velocidad de disolución de un fármaco a diferentes temperaturas, según los valores de entalpía de fusión.', 'La solubilidad de un fármaco a diferentes temperaturas según los valores de entalpía de fusión.', NULL, 'a', NULL, NULL, NULL),
  (2022, 42, '¿Para qué sirve el test de activación de monocitos (MAT)?:', 'Detección y cuantificación de bacterias gramnegativas en preparados de administración parenteral.', 'Detección, in vitro, de pirógenos en preparados de administración parenteral.', 'Detección, in vivo, de pirógenos en preparados de administración parenteral.', 'Detección de monocitos en preparados de administración parenteral.', NULL, 'b', NULL, NULL, NULL),
  (2022, 43, '¿Mediante qué procedimientos se puede obtener agua para preparaciones inyectables de acuerdo con la normativa europea?:', 'Solamente puede obtenerse mediante destilación a partir de agua purificada, apta para elaboración de medicamentos.', 'Solamente puede obtenerse mediante retroósmosis con electro-desionización, a partir de agua purificada, apta para elaboración de medicamentos.', 'Puede obtenerse mediante esterilización por calor a partir de agua potable, apta para consumo humano, y posterior envasado estéril.', 'Puede obtenerse mediante destilación o mediante un proceso equivalente como la retroósmosis con electro-desionización.', NULL, 'd', NULL, NULL, NULL),
  (2022, 44, '¿Cuál de los siguientes parámetros expresa la fluidez de un material pulverulento según la relación entre las densidades apelmazada y aparente?:', 'El índice de Hausner.', 'El parámetro de densificación de Ostwald.', 'El índice de densificación de Heckel.', 'El índice de porosidad.', NULL, 'a', NULL, NULL, NULL),
  (2022, 45, '¿Qué finalidad tienen los sistemas de vectorización activa de fármacos?:', 'Modular la velocidad de liberación del fármaco basándose en el cambio de pH o entorno enzimático, como por ejemplo un comprimido con recubrimiento entérico.', 'Dirigir la liberación del fármaco en un lugar determinado basándose en técnicas que incrementan el tiempo de residencia de la formulación mediante procedimientos de estabilización como la pegilación.', 'Dirigir la liberación del fármaco en un órgano determinado basándose en técnicas de micro o nano encapsulación.', 'Dirigir la liberación del fármaco en un lugar determinado basándose en la unión a ligandos específicos.', NULL, 'd', NULL, NULL, NULL),
  (2022, 46, '¿Deben ser estériles las preparaciones líquidas para inhalación no presurizadas?:', 'Solamente en aquellas destinadas a uso quirúrgico o heridas abiertas.', 'Solo en preparaciones presentadas en dispositivos unidosis, los cuales están exentos de conservantes, o en multidosis que no contengan conservante.', 'No es necesario en ningún caso, ya que estos preparados deben incluir conservantes en su composición salvo que posean propiedades antimicrobianas propias.', 'Sí. Es un requisito indispensable de farmacopea para este tipo de formulaciones, salvo que la formulación presente propiedades antimicrobianas.', NULL, 'b', NULL, NULL, NULL),
  (2022, 47, 'El mecanismo de pulverización por roce o fricción da lugar a partículas con una forma más próxima a la siguiente:', 'Esférica.', 'Acicular.', 'Elipsoide.', 'Dentrítica.', NULL, 'a', NULL, NULL, NULL),
  (2022, 48, 'La presión de pulso es una medida de:', 'La suma de las presiones diastólica y sistólica.', 'El número de latidos cardiacos por minuto.', 'La diferencia entre las presiones arterial y venosa.', 'La diferencia entre las presiones sistólica y diastólica.', NULL, 'd', NULL, NULL, NULL),
  (2022, 49, 'Los factores que determinan la presión de un gas disuelto en un líquido, como, por ejemplo, el aire alveolar y la sangre, se relacionan mediante una de las siguientes leyes:', 'Ley de Ohm.', 'Ley de Henry.', 'Ley de Fick.', 'Ley de Laplace.', NULL, 'b', NULL, NULL, NULL),
  (2022, 50, 'Según la clasificación de sensibilidad de las fibras nerviosas, las del grupo Ib son:', 'Fibras procedentes de las terminaciones anuloespirales de los husos musculares.', 'Fibras procedentes de los órganos tendinosos de Golgi.', 'Fibras procedentes de los órganos táctiles de la piel y de las terminaciones en ramillete.', 'Fibras que conducen la temperatura, el tacto grueso y las sensaciones de dolor y escozor.', NULL, 'b', NULL, NULL, NULL),
  (2022, 51, '¿Cómo se denomina la hendidura o depresión del riñón a través del cual pasan la arteria y venas renales, los vasos linfáticos, la inervación y el uréter?:', 'Hilio renal.', 'Pirámide renal.', 'Pelvis renal.', 'Columna renal.', NULL, 'a', NULL, NULL, NULL),
  (2022, 52, 'Los receptores de estiramiento del arco aórtico y del seno carotídeo:', 'Sirven como barorreceptores que estimulan la secreción de péptido natriurético auricular.', 'Sirven como barorreceptores que afectan la actividad del centro de control vasomotor y cardiaco del bulbo raquídeo.', 'Sirven como osmorreceptores que estimulan la liberación de ADH.', 'Sirven como barorreceptores que estimulan la secreción de renina, aumentando la formación de angiotensina II.', NULL, 'b', NULL, NULL, NULL),
  (2022, 53, '¿Cuál de los siguientes fenómenos está asociado a un desplazamiento hacia la derecha de la curva de disociación de oxígeno-hemoglobina?:', 'Disminución del pH.', 'Disminución de 2,3-difosfoglicerato.', 'Disminución de CO2.', 'Disminución de la temperatura.', NULL, 'a', NULL, NULL, NULL),
  (2022, 54, '¿En cuál de las siguientes células se produce la secreción de gastrina?:', 'Células S del duodeno.', 'Células I del duodeno y del yeyuno.', 'Células G del antro.', 'Células K del duodeno y del yeyuno.', NULL, 'c', NULL, NULL, NULL),
  (2022, 55, '¿Cuál de las siguientes sustancias produce un aumento de la filtración glomerular?:', 'Noradrenalina.', 'Adrenalina.', 'Endotelina.', 'Prostaglandina E2.', NULL, 'd', NULL, NULL, NULL),
  (2022, 56, 'El epitelio que se observa en el esófago de Barret es:', 'Columnar simple.', 'Escamoso estratificado.', 'Columnar estratificado.', 'Escamoso simple.', NULL, 'a', NULL, NULL, NULL),
  (2022, 57, 'El conducto torácico drena la linfa en:', 'La vena yuxtaglomerular derecha.', 'La vena subclavia izquierda.', 'La arteria subaracnoidea.', 'La arteria linfática prefrontal.', NULL, 'b', NULL, NULL, NULL),
  (2022, 58, 'Los órganos accesorios de reproducción masculinos derivan de:', 'Los conductos wolffianos (mesofrénicos).', 'Los conductos mullerianos (paramesofrénicos).', 'Los conductos seminíferos (paramesentéricos).', 'Los conductos antimullerianos (paramesofrénicos).', NULL, 'a', NULL, NULL, NULL),
  (2022, 59, 'La síntesis y liberación de aldosterona ocurren:', 'En la zona glomerular suprarrenal y están reguladas por la angiotensina I.', 'En la zona glomerular suprarrenal y están reguladas por la angiotensina II.', 'En la zona fasciculada suprarrenal y están reguladas por la angiotensina II.', 'En la zona fasciculada suprarrenal y están reguladas por la angiotensina I.', NULL, 'b', NULL, NULL, NULL),
  (2022, 60, '¿Cuál es el orden correcto de maduración de la línea mieloide?:', 'Promielocito, metamielocito, mielocito, cayado.', 'Promielocito, mielocito, metamielocito, cayado.', 'Mielocito, promielocito, metamielocito, cayado.', 'Metamielocito, promielocito, mielocito, cayado.', NULL, 'b', NULL, NULL, NULL),
  (2022, 61, '¿Qué entidad hematológica cursa con una cifra elevada de hematíes, hemoglobina en rango normal o muy próximo a este, y un volumen corpuscular medio (VCM) bajo?:', 'Drepanocitosis.', 'Policitemia vera.', 'Talasemia menor.', 'Anemia ferropénica.', NULL, 'c', NULL, NULL, NULL),
  (2022, 62, 'La presencia en sangre periférica de una cifra anormalmente elevada de linfocitos pequeños con cromatina en “caparazón de tortuga” o “grumelée” es típica de la siguiente neoplasia linfoide:', 'Linfoma-leucemia de Burkitt.', 'Linfoma del manto.', 'Leucemia linfática crónica.', 'Leucemia prolinfocítica B.', NULL, 'c', NULL, NULL, NULL),
  (2022, 63, 'Los hematíes que presentan formas irregulares, con espículas alargadas repartidas de forma asimétrica por la superficie, y que aparecen en pacientes con hepatopatía grave se denominan:', 'Equinocitos.', 'Drepanocitos.', 'Esquistocitos.', 'Acantocitos.', NULL, 'd', NULL, NULL, NULL),
  (2022, 64, 'Señale la respuesta correcta respecto al impacto de las interferencias preanalíticas en los resultados de las pruebas de coagulación:', 'Cuando existe hemoglobina libre después de la centrifugación se altera la línea de base detectada por el analizador, debido a la disminución de absorbancia de la misma a las longitudes de onda usadas en los métodos coagulométricos.', 'La liberación de moléculas citoplasmáticas y de moléculas de membrana pueden activar la coagulación y las plaquetas, generando un sesgo en los resultados del análisis por activación temprana de la coagulación o por consumo de factores de coagulación.', 'La hemólisis de la muestra raramente se debe a problemas en la toma de muestras.', 'Aunque la interferencia por hiperbilirrubinemia se debe a un solapamiento espectral, en el caso de la hipertrigliceridemia la turbidez de la muestra no afecta a la dispersión de la luz.', NULL, 'b', NULL, NULL, NULL),
  (2022, 65, 'Señale la afirmación cierta para la tricoleucemia o leucemia de células peludas clásica:', 'Es una neoplasia de linfocitos T.', 'Es frecuente en niños.', 'Cursa con monocitopenia.', 'Las células presentan un citoplasma altamente basófilo.', NULL, 'c', NULL, NULL, NULL),
  (2022, 66, '¿En cuál de las siguientes entidades hematológicas encontraremos macrotrombocitos?:', 'Trombocitopenia asociada al gen MYH9.', 'Anemia megaloblástica.', 'Anemia aplásica.', 'Leucemia linfoide crónica.', NULL, 'a', NULL, NULL, NULL),
  (2022, 67, 'Un bloqueo cardiaco de primer grado se caracteriza porque:', 'El intervalo PR del electrocardiograma está alargado.', 'Resulta esencial tratarlo con verapamilo, el antiarrítmico de elección en estos casos.', 'La onda T del electrocardiograma está invertida.', 'La onda P del electrocardiograma solamente en ocasiones va seguida de un complejo QRS.', NULL, 'a', NULL, NULL, NULL),
  (2022, 68, 'Señale la afirmación correcta en relación con la degeneración macular asociada a la edad (DMAE) de tipo exudativo o húmeda:', 'La única alternativa disponible para tratarla es el uso de vitaminas C, E y zinc para retrasar su aparición.', 'Se inicia por acumulación de depósitos extracelulares denominados drusas.', 'Es una enfermedad típica de personas jóvenes, entre 20 y 30 años.', 'Los factores de crecimiento vascular endotelial (VEGF) tienen un papel central en su desarrollo.', NULL, 'd', NULL, NULL, NULL),
  (2022, 69, '¿Cuál de las siguientes afirmaciones es correcta en relación a los diferentes tipos de shock?:', 'En un shock séptico refractario, emplear vasopresina por su acción agonista del receptor V1 podría resultar una opción adecuada.', 'Tras una hemorragia masiva, lo más probable es encontrarnos ante un shock distributivo.', 'La noradrenalina se utiliza frecuentemente en los estados de shock para aumentar la frecuencia cardíaca.', 'En un shock cardiogénico no hay manifestaciones de isquemia tisular, como es el aumento de lactato en sangre, a diferencia del resto de subtipos.', NULL, 'a', NULL, NULL, NULL),
  (2022, 70, 'AG es una mujer de 82 años, con antecedentes de hipertensión arterial mal controlada a pesar de recibir tratamiento con ramipril 5 mg cada 24 horas, diabetes mellitus tipo 2 insulinodependiente en seguimiento por endocrinología, y reciente diagnóstico de fibrilación auricular apenas sintomática. ¿Qué actitud sería la más adecuada ante este diagnóstico reciente?:', 'Realizar un control de ritmo con fármacos que ralenticen el paso del impulso cardiaco de las aurículas a los ventrículos y un control de la frecuencia con fármacos que intenten revertir el ritmo a un ritmo sinusal.', 'Dada la edad de la paciente, la actitud más recomendada sería una estrategia conservadora donde no se usen fármacos, priorizando el control del estrés y la modificación del estilo de vida, para mejorar los factores desencadenantes de la fibrilación auricular.', 'La paciente aparentemente cumple criterios para iniciar tratamiento anticoagulante como una de las primeras actitudes a tomar.', 'Es esencial observar el tamaño de las ondas P del electrocardiograma antes de decidir qué hacer.', NULL, 'c', NULL, NULL, NULL),
  (2022, 71, 'Acerca del accidente isquémico transitorio (AIT) es cierto que:', 'Se trata de una lesión isquémica de menos de 24 horas de evolución, detectada radiológicamente (en TC o RMN), sin manifestaciones clínicas, por lo que suele pasar inadvertida para los pacientes.', 'Cuando se diagnostica, es necesario comenzar una triple terapia antiagregante plaquetaria, ya que esta ha demostrado reducir el riesgo de desarrollo posterior de ictus.', 'El factor de riesgo más influyente para desarrollarlo es presentar valores de LDL por encima de los valores de referencia de forma sostenida.', 'Puede aparecer amaurosis fugax, que consiste en la pérdida transitoria de la visión.', NULL, 'd', NULL, NULL, NULL),
  (2022, 72, '¿Cuál de los siguientes trastornos tiene un origen hereditario autosómico dominante?:', 'Distrofia muscular de Duchenne.', 'Hipertermia maligna.', 'Miastenia gravis.', 'Botulismo.', NULL, 'b', NULL, NULL, NULL),
  (2022, 73, 'Con respecto a la formación de cálculos renales:', 'El 80% de los cálculos encontrados están compuestos por ácido úrico.', 'Habitualmente la aparición de cálculos de oxalato cálcico se acompaña de niveles altos de citrato en orina.', 'Los cálculos de fosfato amónico y magnésico son típicos de personas con orina alcalina debido a ciertas infecciones del tracto urinario.', 'Previo al inicio del tratamiento de una leucemia, es importante acidificar la orina para prevenir la formación de cálculos de ácido úrico.', NULL, 'c', NULL, NULL, NULL),
  (2022, 74, 'La fibrosis pulmonar idiopática:', 'Es una enfermedad pulmonar obstructiva.', 'Se diagnostica en la mayoría de los pacientes en la infancia.', 'En la actualidad carece de un tratamiento farmacológico curativo.', 'Puede manifestarse como consecuencia de la utilización de fármacos antagonistas de PD-1.', NULL, 'c', NULL, NULL, NULL),
  (2022, 75, 'En cuanto a las enfermedades relacionadas con la mielina, indique el enunciado correcto:', 'Los anticuerpos anti-acuaporina 4 (AQP4) son patognomónicos de la esclerosis múltiple.', 'Una hiponatremia debe corregirse rápidamente, ya que subidas menores a 8 mmoles/L de sodio diarios pueden conducir a un síndrome de desmielinización osmótica.', 'El bloqueo de la vía del complemento o de la señalización de la interleucina 6 son estrategias útiles para tratar la neuromielitis óptica.', 'Actualmente existen disponibles más fármacos para tratar las formas de esclerosis múltiple progresiva primaria que las formas remitentes-recurrentes.', NULL, 'c', NULL, NULL, NULL),
  (2022, 76, '¿Cuál de las siguientes interleucinas (IL) se asocia con la patogenia del asma y, por tanto, es una diana terapéutica en su tratamiento?:', 'IL-1.', 'IL-5.', 'IL-6.', 'IL-17.', NULL, 'b', NULL, NULL, NULL),
  (2022, 77, 'BT es una paciente mayor que presenta diabetes mellitus tipo 2 en tratamiento con metformina y dapagliflozina, pero no es muy adherente. ¿Cuál de las siguientes complicaciones NO esperaríamos encontrar en ella?:', 'Otitis externa maligna que curse con otalgia y otorrea.', 'Estado de hiperosmolaridad plasmática, acidosis metabólica y elevación de cuerpos cetónicos.', 'Polineuropatía distal simétrica.', 'Edema macular con reducción de la agudeza visual.', NULL, 'b', NULL, NULL, NULL),
  (2022, 78, 'Acerca de las hemorragias digestivas, señale la afirmación correcta:', 'Es esperable un descenso de la frecuencia cardiaca, una disminución de la presión arterial, y un descenso de la hemoglobina.', 'La hematemesis es típica de hemorragias digestivas de tubo alto y las melenas de las hemorragias de tubo digestivo bajo.', 'La hematoquecia puede tener lugar tanto en hemorragias de tubo digestivo alto como en hemorragias de tubo digestivo bajo, si bien es más frecuente en las segundas.', 'La elevación de nitrógeno ureico en sangre es característica de hemorragias de colon debido a la absorción de las proteínas plasmáticas procedentes del sangrado.', NULL, 'c', NULL, NULL, NULL),
  (2022, 79, 'MS es una mujer de 28 años que acude a consulta con múltiples úlceras en la boca, fatiga importante, eritema facial, y dolor articular. Se sospecha entonces de un Lupus Eritematoso Sistémico (LES). ¿Cuál de los siguientes enfoques es correcto?:', 'Si en una analítica los anticuerpos antipéptido citrulinado salieran positivos, la sospecha de LES se afianzaría.', 'El uso de anticuerpos anti-interleucina 2 en estos pacientes mejora la sintomatología.', 'El síndrome de Behçet es una forma específica de LES con afectación fundamentalmente renal.', 'Una característica esperable en esta paciente sería la detección de niveles bajos de factores del complemento.', NULL, 'd', NULL, NULL, NULL),
  (2022, 80, 'Respecto a los antidepresivos, ¿qué asociación de fármaco y mecanismo de acción es INCORRECTA?:', 'Trazodona - Antagonista del receptor 5-HT2.', 'Venlafaxina - Inhibidor de la recaptación de serotonina y noradrenalina (IRSN).', 'Escitalopram - Inhibidor selectivo de la recaptación de serotonina (ISRS).', 'Bupropión - Inhibidor de la monoaminooxidasa (IMAO).', NULL, 'd', NULL, NULL, NULL),
  (2022, 81, '¿Cuál de los siguientes fármacos para el tratamiento de la esclerosis múltiple puede producir rubor facial al inicio del tratamiento?:', 'Dimetilfumarato.', 'Teriflunomida.', 'Natalizumab.', 'Alemtuzumab.', NULL, 'a', NULL, NULL, NULL),
  (2022, 82, 'Pramipexol se utiliza para el tratamiento de:', 'Miastenia gravis.', 'Enfermedad de Parkinson.', 'Esclerosis múltiple.', 'Enfermedad de Alzheimer.', NULL, 'b', NULL, NULL, NULL),
  (2022, 83, '¿Cuál de los siguientes fármacos se utiliza como hipnótico, por sus propiedades sedantes y bajo riesgo de dependencia, en las personas de edad avanzada?:', 'Trazodona.', 'Diazepam.', 'Bupropión.', 'Duloxetina.', NULL, 'a', NULL, NULL, NULL),
  (2022, 84, '¿Cuál de los siguientes anticuerpos monoclonales se utiliza para la profilaxis de la migraña?:', 'Belimumab.', 'Vedolizumab.', 'Galcanezumab.', 'Evolocumab.', NULL, 'c', NULL, NULL, NULL),
  (2022, 85, '¿Cuál de las siguientes afirmaciones es correcta con relación al tratamiento de la enfermedad pulmonar obstructiva crónica (EPOC)?:', 'El efecto secundario más frecuente de los agonistas muscarínicos anticolinérgicos es la sequedad bucal.', 'La utilización prolongada de corticoides inhalados se ha asociado con candidiasis orofaríngea y pérdida de densidad ósea.', 'Se recomienda el uso continuado de corticoides orales debido a su buen perfil de seguridad.', 'El papel principal de los corticoides inhalados es emplearse como tratamiento agudo de las exacerbaciones.', NULL, 'b', NULL, NULL, NULL),
  (2022, 86, 'Se presenta el caso de un paciente con enfermedad renal crónica en diálisis peritoneal y tratamiento con agentes estimulantes de la eritropoyesis. ¿Cuál de las siguientes afirmaciones es correcta?:', 'No es importante conocer las reservas férricas en médula ósea para asegurar una respuesta adecuada al tratamiento con agentes estimulantes de la eritropoyesis, ya que estos funcionan independientemente de la cantidad de hierro del organismo.', 'La diálisis peritoneal se acompaña de diversas complicaciones metabólicas como la hipoproteinemia.', 'Una de las complicaciones frecuentes de la diálisis es la hipoglucemia.', 'Cuando utilizamos agentes estimulantes de la eritropoyesis, buscamos conseguir subidas muy rápidas de hemoglobina, por encima de los 3 g/dL al mes.', NULL, 'b', NULL, NULL, NULL),
  (2022, 87, '¿Cuál de las siguientes vacunas se formula con agentes atenuados?:', 'Vacuna de la hepatitis B.', 'Vacuna de la fiebre amarilla.', 'Vacuna de la rabia.', 'Vacuna del papilomavirus.', NULL, 'b', NULL, NULL, NULL),
  (2022, 88, '¿Cuál de las siguientes afirmaciones referidas al manejo del estreñimiento es FALSA?:', 'Los preparados de fosfato de sodio son el tratamiento de elección en pacientes de edad avanzada o con insuficiencia renal.', 'Naloxegol está indicado para el tratamiento del estreñimiento inducido por opioides.', 'Los laxantes formadores del bolo pueden provocar distensión abdominal y meteorismo.', 'El uso a largo plazo de laxantes lubricantes y emolientes puede provocar una malabsorción de vitaminas liposolubles.', NULL, 'a', NULL, NULL, NULL),
  (2022, 89, 'Algunos fármacos se caracterizan por tener la capacidad de producir efectos adversos anticolinérgicos, especialmente en pacientes de edad avanzada. ¿Cuál de los siguientes grupos de fármacos NO presenta una elevada potencia anticolinérgica?:', 'Antidepresivos tricíclicos (amitriptilina).', 'Antihistamínicos de 1ª generación (doxilamina).', 'Antiespasmódicos urinarios (tolterodina).', 'Antimigrañosos (sumatriptán).', NULL, 'd', NULL, NULL, NULL),
  (2022, 90, 'Se presenta un paciente con adenocarcinoma de pulmón en estadio IV, con metástasis óseas y hepáticas. En el estudio de biomarcadores de una muestra del pulmón biopsiada se obtiene el siguiente resultado: EGFR mutado (Ex19Del), HER2 negativo, BRAF nativo, reordenamiento ALK negativo, fusión ROS 1 negativa, PDL-1 negativo, ¿cuál sería el tratamiento adecuado?:', 'Lapatinib.', 'Crizotinib.', 'Osimertinib.', 'Dabrafenib.', NULL, 'c', NULL, NULL, NULL),
  (2022, 91, 'Paciente con SIDA en tratamiento con darunavir/cobicistat que ingresa en el hospital. Nos realizan una consulta sobre el hipnótico/ansiolítico adecuado para tratar el insomnio que padece acompañado de ansiedad, entre los disponibles en el hospital. ¿Cuál es la respuesta correcta?:', 'Lorazepam.', 'Midazolam.', 'Diazepam.', 'Triazolam.', NULL, 'a', NULL, NULL, NULL),
  (2022, 92, '¿Cuál de las siguientes afirmaciones es correcta con relación al tratamiento del cáncer?:', 'Los efectos inmunomediados graves producidos por la inmunoterapia pueden tratarse con corticoides.', 'La hipotensión es un efecto adverso muy frecuente de bevacizumab y de otros medicamentos antiangiogénicos.', 'Rituximab es un anticuerpo monoclonal dirigido al antígeno CD33.', 'Los inmunoterápicos con diferentes blancos (PD-1 y CTLA-4) no deben combinarse en el tratamiento del cáncer.', NULL, 'a', NULL, NULL, NULL),
  (2022, 93, 'Señale la asociación correcta en relación con la infección por el virus de la inmunodeficiencia humana (VIH):', 'Candidiasis esofágica – Etapa 1 de la infección VIH (CDC).', 'Combinaciones con tenofovir disoproxilo – Osteomalacia.', 'Combinaciones con enfavurtida – Tratamiento de infección por VIH-2.', 'ARN de VIH en <50 copias/mL – Alto riesgo de enfermedades oportunistas.', NULL, 'b', NULL, NULL, NULL),
  (2022, 94, '¿Cuál de las siguientes respuestas es correcta con respecto al síndrome de hipersensibilidad al alopurinol (AHS)?:', 'Los síntomas ocurren después de 3-5 días del inicio del tratamiento.', 'La disfunción hepática favorece su desencadenamiento.', 'La prevalencia es mayor en pacientes de ascendencia coreana o tailandesa frente a pacientes caucásicos.', 'Es bastante frecuente y benigno, por lo general se resuelve disminuyendo la dosis de alopurinol.', NULL, 'c', NULL, NULL, NULL),
  (2022, 95, 'Indique la respuesta INCORRECTA sobre los preparados de insulina de acción prolongada:', 'La afinidad de la insulina detemir es 4-5 veces menor que la de la insulina soluble por lo que se formula a una concentración mayor.', 'La insulina glargina se formula a un pH básico para mantener la solubilidad.', 'En la insulina degludec, los monómeros se liberan constantemente en la circulación sistémica y su duración de acción es mayor de 42 h.', 'En la insulina NPH la dosis regula el perfil de acción; las dosis pequeñas tienen picos más bajos, más tempranos, y una acción de corta duración.', NULL, 'b', NULL, NULL, NULL),
  (2022, 96, '¿Cuál de las siguientes afirmaciones sobre repaglinida es correcta?', 'Presenta un inicio de acción lento con una concentración máxima y efecto máximo de alrededor de 3 h después de la ingestión.', 'No hay riesgo de hipoglucemia si una vez que se toma el medicamento la comida se retrasa o se omite.', 'Se puede usar en pacientes con insuficiencia renal y de edad avanzada.', 'Contiene azufre en su estructura por lo que no puede emplearse en diabéticos tipo 2 con alergia a las sulfonilureas.', NULL, 'c', NULL, NULL, NULL),
  (2022, 97, 'En relación con los receptores acoplados a proteínas G (RAPG), señale la opción correcta:', 'Las β-arrestinas forman complejos con los RAPG fosforilados.', 'El complejo RAPG-agonista interactúa directamente con clatrina antes de internalizarse.', 'Los RAPG ocupados por un agonista se unen a las proteínas G solamente cuando han sido fosforilados previamente por las cinasas de receptores acoplados a proteínas G (GRK).', 'Los complejos β-arrestina-RAPG son sistemáticamente degradados.', NULL, 'a', NULL, NULL, NULL),
  (2022, 98, 'En relación con los fármacos que se comportan como antagonistas competitivos, señale la opción correcta:', 'En su presencia, disminuye la concentración eficaz 50 (CE50) de los agonistas puros del mismo receptor.', 'En su presencia, disminuye el efecto máximo de los agonistas puros del mismo receptor.', 'Disminuyen la eficacia, pero no la potencia, de los agonistas puros del mismo receptor.', 'Disminuyen la potencia, pero no la eficacia, de los agonistas puros del mismo receptor.', NULL, 'd', NULL, NULL, NULL),
  (2022, 99, 'En relación con anakinra, señale la opción correcta:', 'Es una proteína de fusión compuesta por el receptor p75 del factor de necrosis tumoral (TNF) y la porción Fc de la IgG1 humana.', 'Inhibe la unión de CD80 al receptor CD28 en los linfocitos T.', 'Es un receptor de factor de necrosis tumoral recombinante que inhibe la unión de TNFα a su receptor.', 'Es un receptor de interleucina 1 (IL-1) recombinante que inhibe la unión de la IL-1α a su receptor.', NULL, 'd', NULL, NULL, NULL),
  (2022, 100, 'Señalar la opción correcta en relación con el tramadol:', 'Es un opioide desprovisto de riesgo de tolerancia y dependencia.', 'Su acción agonista opioide se debe fundamentalmente a uno de sus metabolitos.', 'Es tan eficaz como la morfina para el tratamiento del dolor severo.', 'Se utiliza preferentemente como antitusivo.', NULL, 'b', NULL, NULL, NULL),
  (2022, 101, 'La Kd (constante de disociación) de un fármaco:', 'Coincide con la CE50 (concentración eficaz 50) de dicho fármaco.', 'Se corresponde con la concentración de fármaco que ocupa la mitad de los receptores existentes en el sistema en estudio.', 'Es independiente de la afinidad del fármaco por su receptor.', 'Depende de la eficacia del fármaco.', NULL, 'b', NULL, NULL, NULL),
  (2022, 102, 'Señale la respuesta correcta sobre los fármacos del grupo de los tioureilenos, empleados en las enfermedades tiroideas:', 'Son análogos sintéticos de la tiroxina (T4).', 'Tienen como mecanismo de acción la inhibición de la enzima tiroperoxidasa, reduciendo con ello la yodación de los residuos de la tiroglobulina.', 'Poseen acción citotóxica sobre las células de los folículos tiroideos.', 'Solo son empleados en cuadros de hipotiroidismo severo debido a su elevada potencia.', NULL, 'b', NULL, NULL, NULL),
  (2022, 103, 'La forma farmacéutica y el tamaño de las partículas influyen sobre el proceso de absorción del fármaco, cuando éste es administrado por vía oral, al condicionar:', 'La disgregación.', 'La eliminación del principio activo.', 'El volumen de distribución.', 'La excreción renal.', NULL, 'a', NULL, NULL, NULL),
  (2022, 104, '¿Cuál de las siguientes es una reacción metabólica de fase I?:', 'Desulfuración.', 'Glucuronidación', 'Acetilación.', 'Descarboxilación.', NULL, 'a', NULL, NULL, NULL),
  (2022, 105, '¿Qué tipo de fármaco se utiliza para disminuir los efectos secundarios periféricos de la levodopa, en pacientes con enfermedad de Parkinson?:', 'Antagonistas colinérgicos.', 'Agonistas dopaminérgicos no ergóticos.', 'Inhibidores de la MAO-B (monoaminooxidasa-B).', 'Inhibidores periféricos de la LAAD (L-aminoácido aromático-descarboxilasa).', NULL, 'd', NULL, NULL, NULL),
  (2022, 106, '¿Cuál de las siguientes afirmaciones con relación a los fármacos pertenecientes al grupo de los bisfosfonatos es correcta?:', 'Su uso a largo plazo se relaciona con fracturas atípicas de fémur, algo que no sucede con el denosumab.', 'El ácido aledrónico es el bifosfonato más potente de todos los disponibles.', 'Tienen una pobre absorción oral por lo que se recomienda su administración en ayunas.', 'Su mecanismo de acción se basa en la formación de hueso.', NULL, 'c', NULL, NULL, NULL),
  (2022, 107, 'En relación con la lamotrigina, señale la opción INCORRECTA:', 'Entre otros, bloquea receptores metabotrópicos de glutamato.', 'Está indicada en el tratamiento del trastorno bipolar, pero solo para la prevención de los episodios depresivos.', 'Su espectro de acción es amplio, pudiéndose emplear tanto en crisis parciales como generalizadas.', 'Es un antiepiléptico que presenta menor evidencia de teratogenicidad que otros como el valproato.', NULL, 'a', NULL, NULL, NULL),
  (2022, 108, 'En relación con el uso de β-bloqueantes en el tratamiento de la cardiopatía isquémica, señale la opción correcta:', 'La discontinuación abrupta de un tratamiento con β-bloqueantes puede aumentar el riesgo de muerte súbita.', 'Están indicados en monoterapia en el tratamiento de la angina vasoespástica (angina en reposo).', 'En el miocardio isquémico, los β-bloqueantes aumentan el aporte de oxígeno, pero no tienen efecto neto sobre su consumo.', 'Los β-bloqueantes son muy útiles en pacientes diabéticos al mejorar su control de la glucemia.', NULL, 'a', NULL, NULL, NULL),
  (2022, 109, 'Referidos a Glicirryza glabra, indique cuál de las siguientes afirmaciones es FALSA:', 'Contiene glicirricina, un saponósido triterpénico pentacíclico.', 'La droga está constituida por la raíz.', 'Entre sus principios activos se encuentran otros saponósidos como el liquiritósido.', 'Tiene acción mineralocorticoide.', NULL, 'c', NULL, NULL, NULL),
  (2022, 110, '¿Cuál de las siguientes afirmaciones es correcta?:', 'A partir del fruto de Pygeum africanum se obtiene un extracto acuoso que se emplea en el tratamiento de la hipertrofia benigna de próstata.', 'A partir de las cortezas de Rhamnus purshianus se obtienen O-heterósidos y C-heterósidos con estructura de emodina antrona.', 'El oleuropeósido es uno de los ácidos grasos presentes en el aceite de oliva.', 'El aceite obtenido de las semillas de Oenothera biennis contiene como componente mayoritario triglicéridos formados por ácidos grasos saturados.', NULL, 'b', NULL, NULL, NULL),
  (2022, 111, 'Indique cuál de las siguientes expresiones es la correcta:', 'Las cumarinas se consideran derivados fenólicos que biogenéticamente se originan por la vía del ácido sikímico.', 'El rizoma de Centella asiática contiene asiaticósido, una saponina triterpénica pentacíclica.', 'El salicósido se extrae de las hojas de Salix alba.', 'La d-tubocurarina actúa como antagonista de acetilcolina sobre receptores muscarínicos en placa motora.', NULL, 'a', NULL, NULL, NULL),
  (2022, 112, '¿Para cuál de los siguientes fármacos no tendría interés clínico realizar una prueba farmacogenética que midiera la actividad de alguna enzima responsable de su metabolismo?:', 'Etanercept.', 'Aripiprazol.', 'Tacrolimus.', '5-Fluorouracilo.', NULL, 'a', NULL, NULL, NULL),
  (2022, 113, '¿En cuál de las siguientes vías de administración de fármacos el tipo de estrato que regula la absorción se considera subcelular?:', 'Parenteral extravascular.', 'Oral.', 'Transpulmonar.', 'Percutánea.', NULL, 'a', NULL, NULL, NULL),
  (2022, 114, 'Acaba de prepararse en la farmacia del hospital una suspensión de un fármaco que presenta hidrólisis en medio ácido. ¿Cuál de las siguientes formas de administración presentará una mayor biodisponibilidad?:', 'Por una sonda nasoyeyunal.', 'Por la vía oral fisiológica.', 'Por una gastrostomía endoscópica percutánea (PEG).', 'Por una sonda nasogástrica.', NULL, 'a', NULL, NULL, NULL),
  (2022, 115, '¿Cuál de los siguientes enunciados en relación a la actividad de la glicoproteína P y el proceso de absorción es correcto?:', 'La amiodarona actúa a nivel de la glicoproteína P intestinal, dificultando la absorción de fármacos que son sustrato de esta.', 'Se considera un transporte pasivo, ya que su actividad es ATP-independiente.', 'En el ser humano se encuentra fundamentalmente a nivel del tracto gastrointestinal, aunque también está presente en otros lugares, como la barrera hematotesticular. Sin embargo, la barrera hematoencefálica carece de ella.', 'El dabigatrán es un ejemplo de fármaco que requiere una reducción de dosis cuando se administra con inhibidores de glicoproteína P.', NULL, 'd', NULL, NULL, NULL),
  (2022, 116, 'Acude a urgencias un paciente con COVID-19, al que le prescriben nilmatrevir/ritonavir. El paciente toma además ibrutinib de forma crónica para tratar su leucemia linfocítica crónica, un fármaco metabolizado a nivel hepático. ¿Qué podríamos esperar en este paciente con respecto a su tratamiento?:', 'La fuerte inducción de los citocromos producida por ritonavir podría causar una disminución de los niveles plasmáticos de ibrutinib, reduciendo su eficacia.', 'A pesar de que la eliminación de ibrutinib es principalmente hepática, el bloqueo de los transportadores activos renales causado por ritonavir podría provocar cambios en los niveles plasmáticos de ibrutinib, aumentándolos.', 'El ritonavir es un inhibidor importante del citocromo 3A, incrementando por tanto los niveles de ibrutinib, y con ello posiblemente su toxicidad.', 'Al ser un tratamiento de 5 días, se puede considerar que el uso de fármacos inhibidores o inductores del metabolismo durante periodos de tiempo tan cortos no van a modificar los niveles plasmáticos de otros fármacos.', NULL, 'c', NULL, NULL, NULL),
  (2022, 117, '¿A qué tipo de proceso cinético se ajustan habitualmente la filtración glomerular y la reabsorción tubular pasiva?:', 'Ambas a procesos cinéticos de primer orden.', 'Ambas a procesos cinéticos de orden cero.', 'La filtración glomerular a cinética de primer orden y la reabsorción tubular pasiva a cinética de orden cero.', 'La filtración glomerular a cinética de orden cero y la reabsorción tubular pasiva a cinética de primer orden.', NULL, 'a', NULL, NULL, NULL),
  (2022, 118, 'En el análisis farmacocinético modelo-dependiente de curvas de niveles plasmáticos – tiempo tras administración extravasal, el cálculo del período de latencia se realiza a partir de:', 'La fase lineal terminal de la representación semilogarítmica de niveles plasmáticos – tiempo.', 'La fase inicial de la curva de niveles plasmáticos – tiempo.', 'La pendiente de la fase lineal terminal de la curva de niveles plasmáticos – tiempo.', 'El tiempo al que se produce la intersección de las rectas semilogarítmicas extrapoladas con el eje de ordenadas correspondiente a las fases de absorción y de eliminación.', NULL, 'd', NULL, NULL, NULL),
  (2022, 119, '¿Cuál de las siguientes es una característica de la farmacocinética no lineal?:', 'Los parámetros farmacocinéticos no se mantienen constantes e independientes de la dosis administrada y del tiempo.', 'Los parámetros farmacocinéticos se mantienen constantes e independientes de la dosis administrada y del tiempo.', 'Se cumple el principio de superposición de las curvas de niveles plasmáticos – tiempo a distintas dosis.', 'Todos los procesos que experimenta el fármaco en el organismo se ajustan a cinéticas de primer orden.', NULL, 'a', NULL, NULL, NULL),
  (2022, 120, 'Respecto a la farmacocinética de la digoxina, podemos afirmar que:', 'La biodisponibilidad de los comprimidos es próxima al 100%.', 'Algunos fármacos como la quinidina y el verapamilo disminuyen las concentraciones séricas de digoxina por aumento de la eliminación renal.', 'Presenta un volumen de distribución de aproximadamente 0,1 L/Kg por su elevada unión a proteínas plasmáticas.', 'La principal vía de eliminación de la digoxina es a través de procesos de filtración glomerular del riñón.', NULL, 'd', NULL, NULL, NULL),
  (2022, 121, 'En administración extravasal, el fenómeno denominado de flip-flop ocurre cuando:', 'El proceso de absorción es más rápido que el de eliminación.', 'El proceso de eliminación es más rápido que el de absorción.', 'El proceso de absorción se produce a la misma velocidad que el de eliminación.', 'El proceso de liberación del fármaco de la forma de dosificación limita su absorción.', NULL, 'b', NULL, NULL, NULL),
  (2022, 122, '¿Cuál de las siguientes afirmaciones es FALSA respecto a la dosis de choque de un medicamento administrado por vía intravenosa?:', 'La dosis de choque necesaria para alcanzar la concentración plasmática objetivo está determinada por el volumen de distribución.', 'Cuando el intervalo de administración es igual a la semivida del fármaco, una dosis de choque de dos veces la dosis de mantenimiento lograría alcanzar el estado de equilibrio.', 'La dosis de choque es independiente de la concentración plasmática objetivo, al depender solamente de su eliminación.', 'Es una estrategia de dosificación establecida para muchos fármacos con semivida de eliminación elevada.', NULL, 'c', NULL, NULL, NULL),
  (2022, 123, 'La proteína quinasa dependiente de AMP o AMP quinasa, es uno de los principales reguladores de la homeostasis metabólica. En su forma activa, esta enzima produce:', 'La inhibición de la glucolisis y de la glucogenólisis muscular.', 'La inhibición hepática de la lipogénesis y de la colesterogénesis.', 'La activación de la síntesis de ácidos grasos en adipocitos.', 'La activación de la fosfoenolpiruvato carboxiquinasa (PEPCK) y la consiguiente estimulación de la gluconeogénesis hepática.', NULL, 'b', NULL, NULL, NULL),
  (2022, 124, 'Indique cuál de estas etapas del ciclo de Krebs está sometida a regulación alostérica:', 'Isocitrato - α-cetoglutarato.', 'Citrato - isocitrato.', 'Succinil-CoA - succinato.', 'Fumarato - malato.', NULL, 'a', NULL, NULL, NULL),
  (2022, 125, '¿Cuál de las siguientes funciones NO la realiza un derivado del isopreno?:', 'Regular el metabolismo del calcio.', 'Provocar la respuesta inflamatoria y fiebre.', 'Estimular la proliferación de la mucosa endometrial del útero.', 'Incrementar la reabsorción de sodio y secreción de potasio.', NULL, 'b', NULL, NULL, NULL),
  (2022, 126, '¿Cuál de las siguientes afirmaciones acerca del ciclo del ácido cítrico, también conocido como ciclo de Krebs o ciclo de los ácidos tricarboxílicos, es correcta?:', 'Es un ciclo reversible, que puede funcionar en ambas direcciones.', 'El calcio (Ca2+) es un potente inhibidor del ciclo, actuando sobre la isocitrato deshidrogenasa y la α-cetoglutarato deshidrogenasa.', 'La succinil-CoA sintetasa, anclada en la membrana mitocondrial interna, forma parte del complejo II de la cadena de transporte electrónico.', 'El ciclo cataliza la oxidación de acetil-CoA a CO2, generando NADH+H+, FADH2 y GTP, aunque la enzima fumarasa no participa en la producción de ninguna de estas moléculas mencionadas.', NULL, 'd', NULL, NULL, NULL),
  (2022, 127, '¿Dónde tienen lugar de forma casi exclusiva las reacciones del ciclo de la urea?:', 'En el músculo esquelético.', 'En el hígado.', 'En el riñón.', 'En la mucosa intestinal.', NULL, 'b', NULL, NULL, NULL),
  (2022, 128, 'Un paciente fue sometido a una pancreaticoduodenectomía (resección completa del duodeno, de la vesícula biliar y de la cabeza del páncreas) hace 6 meses. Ha recibido múltiples ciclos de antibióticos de amplio espectro por haber sido colonizado por una bacteria multirresistente durante el ingreso, y actualmente presenta hematuria. ¿Qué afirmación sería más probable?:', 'Debido a una resección de este tipo y el uso prolongado de antibióticos, la hematuria podría ser secundaria a una deficiencia de naftoquinonas.', 'Debido a la resección parcial del páncreas y total de la vesícula biliar, la hematuria podría ser secundaria a una trombopenia por deficiencia de tocoferol.', 'Debido a la resección duodenal, la hematuria podría ser secundaria a un déficit de absorción de vitamina B12.', 'Debido a la resección duodenal, la hematuria podría ser una de las hemorragias típicas de la púrpura Schoenlein-Henoch, causada por déficit de vitaminas liposolubles.', NULL, 'a', NULL, NULL, NULL),
  (2022, 129, 'Señale qué respuesta es INCORRECTA en relación a los heteropolisacáridos:', 'El ácido hialurónico es el glicosaminoglicano que más comúnmente se encuentra formando la parte glucídica de los proteoglicanos.', 'Los proteoglicanos son heterósidos que presentan un porcentaje mayor de glúcidos que las glucoproteínas.', 'El fondaparinux es un fármaco anticoagulante que presenta una secuencia heteropolisacarídica semejante a la heparina, a la que se ha añadido un grupo metoxilo.', 'Los glicosaminoglicanos están formados por unidades monosacarídicas distintas, una de las cuales es siempre N-acetilglucosamina o N-acetilgalactosamina.', NULL, 'a', NULL, NULL, NULL),
  (2022, 130, '¿En cuál de las siguientes acciones esperaría que un mayor porcentaje de la producción de ATP procediera del sistema oxidativo?:', 'Esprintar durante un partido de tenis (10 segundos, uso mayoritario de musculatura de miembros inferiores).', 'Realizar una tanda de 30 flexiones (60 segundos, uso mayoritario de musculatura de pecho y miembros superiores).', 'Jugar una partida de ajedrez contra Hans Niemann (30 minutos, sin uso mayoritario de ninguna musculatura).', 'Competir en una prueba de natación de 100 m mariposa (70 segundos, uso de miembros superiores, inferiores y pecho).', NULL, 'c', NULL, NULL, NULL),
  (2022, 131, '¿Con respecto al metabolismo hepático del alcohol (etanol), qué afirmación es correcta?:', 'Se inicia con una descarboxilación oxidativa catalizada por la enzima alcohol descarboxilasa.', 'Genera un exceso de acetil-CoA que se puede utilizar para la síntesis de ácidos grasos.', 'Provoca un aumento del pH sanguíneo debido a la acción final de la enzima acetaldehído deshidrogenasa.', 'Para ser metabolizado, se consume NADH y se genera en consecuencia NAD+.', NULL, 'b', NULL, NULL, NULL),
  (2022, 132, '¿Qué papel desempeña la apoproteína E en la eliminación de remanentes de quilomicrones y de lipoproteínas de muy baja densidad (VLDL) de la circulación sanguínea?:', 'Favorece la transferencia de material lipídico de ambas lipoproteínas a las HDL.', 'Es reconocida por los receptores celulares hepáticos que pertenecen a la familia de receptores de lipoproteínas de baja densidad.', 'Actúa como cofactor activador de la lipoproteín lipasa sérica.', 'Estabiliza la estructura de las lipoproteínas y desaparece de ellas por la cesión de ácidos grasos a las células periféricas.', NULL, 'b', NULL, NULL, NULL),
  (2022, 133, 'En relación a las endonucleasas de restricción, ¿qué afirmación es INCORRECTA?:', 'Reconocen secuencias palindrómicas; GATC sería un ejemplo de estas.', 'Cortan la molécula de ADN en un sitio preciso.', 'No se pueden emplear en procesos de clonación debido a su termolabilidad, quedando restringidas a procesos de modificación génica más sencillos.', 'Pueden originar extremos tanto romos como cohesivos, dependiendo de la enzima.', NULL, 'c', NULL, NULL, NULL),
  (2022, 134, 'En relación con los ARNm policistrónicos, ¿qué afirmación es cierta?', 'A pesar de ser muy largos, codifican una sola proteína.', 'Se sintetizan en el interior del núcleo celular para luego salir de este y traducirse en el citoplasma.', 'Una de sus características particulares es que son los únicos ARNm donde encontramos codones formados por 4 bases, en lugar de 3.', 'Los podemos encontrar en procariotas y virus, pero no en eucariotas.', NULL, 'd', NULL, NULL, NULL),
  (2022, 135, '¿Cuál de las siguientes opciones NO es una mutación puntual en la secuencia de ADN?:', 'Sustitución.', 'Deleción.', 'Inserción.', 'Traslocación.', NULL, 'd', NULL, NULL, NULL),
  (2022, 136, 'En cuanto a la estructura helicoidal de la conformación A y B del ADN bicatenario, ¿qué afirmación es cierta?:', 'Ambas conformaciones presentan una hélice con vuelta a la izquierda (ADN-levógiro).', 'Ambas conformaciones presentan una hélice con vuelta a la derecha (ADN-dextrógiro).', 'La conformación A presenta una hélice con vuelta a la derecha (ADN-dextrógiro) y la conformación B presenta una hélice con vuelta a la izquierda (ADN-levógiro).', 'La conformación A presenta una hélice con vuelta a la izquierda (ADN-levógiro) y la conformación B presenta una hélice con vuelta a la derecha (ADN-dextrógiro).', NULL, 'b', NULL, NULL, NULL),
  (2022, 137, '¿Cuál de las siguientes opciones NO es un sistema de reparación del ADN?:', 'Reparación por escisión de bases.', 'Reparación por supresión de nucleótidos.', 'Reparación de emparejamientos de la hebra simple.', 'Reparación de pares erróneos.', NULL, 'c', NULL, NULL, NULL),
  (2022, 138, '¿En cuál de los siguientes casos esperamos encontrar una cantidad de cobre elevada en la orina?:', 'Paciente con enfermedad de Menkes.', 'Paciente con una patología que curse con un déficit en la síntesis de ceruloplasmina.', 'Paciente que ingiere grandes cantidades de zinc de forma crónica.', 'Paciente con mutaciones en el transportador codificado por el gen ATP7A.', NULL, 'b', NULL, NULL, NULL),
  (2022, 139, 'AR es una paciente que ingresa para tratarse de un linfoma, y tiene un diagnóstico de déficit grave de glucosa 6 fosfato deshidrogenasa. Al revisar su prescripción, usted se encuentra con que uno de los fármacos que recibe presenta especial riesgo de desencadenar una crisis de anemia hemolítica. ¿Cuál es ese fármaco?', 'Meropenem.', 'Tramadol.', 'Rasburicasa.', 'Bisoprolol.', NULL, 'c', NULL, NULL, NULL),
  (2022, 140, 'Respecto al aminoácido cisteína, señale el enunciado correcto:', 'Es uno de los aminoácidos esenciales en el adulto.', 'Tiene capacidad de absorber luz ultravioleta a 280 nm.', 'Forma parte del tetrapéptido glutatión, que protege de la oxidación a través de la enzima glutatión peroxidasa.', 'Se clasifica generalmente como polar a pesar de tener un índice hidropático positivo.', NULL, 'd', NULL, NULL, NULL),
  (2022, 141, 'MB es un paciente de 73 años ingresado tras una cirugía de colon por su proceso oncológico de base. El cirujano le prescribe una nutrición parenteral estandarizada, ya que el paciente padece de íleo paralítico tras la operación y lleva varios días de ayuno. Al día siguiente, en la analítica presenta hipofosfatemia, hipomagnesemia e hipopotasemia, así como déficit de vitamina B1. ¿Cuál es el escenario más probable que explica esta situación?:', 'Las nutriciones parenterales comerciales carecen de electrolitos, por lo que deberían haberse añadido en el Servicio de Farmacia.', 'Debido al proceso de base, el paciente se encontraba desnutrido y parece presentar un síndrome de realimentación tras el inicio de la nutrición.', 'La nutrición parenteral ha interaccionado con la medicación que toma el paciente provocando una desregulación electrolítica.', 'Esta es una situación habitual en pacientes de edad avanzada, que responden mal a tratamientos con nutrición parenteral.', NULL, 'b', NULL, NULL, NULL),
  (2022, 142, 'En una muestra de un paciente, nos encontramos con LDH y K+ elevados, y la haptoglobina disminuida. ¿Cuál de las siguientes patologías es más probable?:', 'Déficit de piruvato quinasa.', 'Síndrome de Lesch-Nyhan.', 'Síndrome de Hurler.', 'Hiperpotasemia franca con anemia por insuficiencia renal crónica.', NULL, 'a', NULL, NULL, NULL),
  (2022, 143, 'La imagen adjunta muestra un proteinograma de un individuo sano y de un paciente en estudio. ¿Qué alteración es la más probable para este caso?', 'Hipoalbuminemia.', 'Inflamación crónica.', 'Inmunodeficiencia.', 'Paraproteinemia o gammapatía monoclonal.', NULL, 'c', NULL, NULL, 'sin_imagen'),
  (2022, 144, 'Cuando un aparato de análisis de muestras de sangre nos da el valor de índice sérico, este hace referencia a:', 'Un índice que mide el grado de anemia del paciente de forma precisa.', 'Un indicador de la calidad de la muestra, que nos informa de la validez de los resultados que podamos obtener.', 'Una medida de la celularidad del suero, que informa tanto de los hematíes presentes como de los leucocitos.', 'Un índice cuantitativo que calcula la cantidad de proteínas séricas presentes, si bien no hace distinciones entre proteínas α-1 y α-2.', NULL, 'b', NULL, NULL, NULL),
  (2022, 145, 'Los métodos homogéneos directos para la cuantificación del colesterol-HDL permiten determinar el colesterol-no-HDL. ¿Qué lipoproteínas engloba esta fracción lipoproteica?:', 'LDL.', 'IDL y LDL.', 'VLDL y lipoproteínas remanentes.', 'Quilomicrones, VLDL, IDL y LDL.', NULL, 'd', NULL, NULL, NULL),
  (2022, 146, 'En un paciente con un diagnóstico de ictericia a causa de una anemia hemolítica, ¿cuál de las siguientes afirmaciones es INCORRECTA?:', 'Presentará una hiperbilirrubinemia a expensas de un aumento de la bilirrubina indirecta.', 'Es esperable que se produzca un incremento de bilirrubina en la orina.', 'Se producirá un descenso de la haptoglobina, y un aumento de la lactato deshidrogenasa.', 'Suelen presentar un índice de producción de reticulocitos mayor o igual a 2,5 veces el valor normal.', NULL, 'b', NULL, NULL, NULL),
  (2022, 147, '¿Cuál es la explicación más probable para los resultados del siguiente urianálisis? Nitrito (2+), Esterasa Leucocitaria (3+), Cetonas (Negativo), Glucosa (trazas):', 'Contaminación de la muestra por mala manipulación.', 'Infección del tracto urinario.', 'Anorexia o ayuno muy prolongado.', 'Incapacidad glomerular para la conservación de macromoléculas.', NULL, 'b', NULL, NULL, NULL),
  (2022, 148, 'ML es una mujer de 86 años que consulta por mal estado general. Como antecedentes personales destacan diabetes y enfermedad por reflujo gastroesofágico en tratamiento con omeprazol desde hace 10 días. Se encuentra afebril, y una tira de orina revela hematuria y leucocituria, con nitritos negativos. Analíticamente destaca un filtrado glomerular de 40 mL/min (CKD-EPI) y unas proteínas en orina de 24 horas ligeramente elevadas. En una analítica de hace 30 días el filtrado glomerular era normal (100 mL/min). ¿Cuál de los siguientes diagnósticos sería el más probable?:', 'Nefritis intersticial aguda.', 'Nefropatía diabética.', 'Síndrome nefrótico.', 'Infección del tracto urinario.', NULL, 'a', NULL, NULL, NULL),
  (2022, 149, 'Tras iniciar tratamiento quimioterápico en un paciente hematológico con alta carga de enfermedad, ¿cuál de las siguientes alteraciones hidroelectrolíticas sería más probable encontrar?:', 'Hiperfosfatemia.', 'Hipernatremia.', 'Hipercalcemia.', 'Hipomagnesemia.', NULL, 'a', NULL, NULL, NULL),
  (2022, 150, 'Un recién nacido de 72 horas de vida debuta con un cuadro de hiperamonemia, sospechándose un error congénito del metabolismo. Analíticamente destaca la ausencia de acidosis, así como unos niveles de citrulina en plasma bajos, y un nivel elevado de ácido orótico en orina. ¿Cuál sería el diagnóstico más probable?:', 'Déficit de carbamil-P-sintetasa 1.', 'Enfermedad del jarabe de arce.', 'Déficit de ornitín transcarbamilasa.', 'Déficit de piruvato deshidrogenasa.', NULL, 'c', NULL, NULL, NULL),
  (2022, 151, 'De los siguientes ácidos, ¿cuál es el más apropiado para preparar una disolución tampón de pH=5?:', 'Ácido fosfórico, (pKa1 = 2,14; pKa2 = 7,19; pKa3 = 12,34).', 'Ácido carbónico, (pKa1 = 6,35; pKa2 = 10,32).', 'Ácido acético, (pKa = 4,75).', 'Ácido hipocloroso, (pKa = 7,52).', NULL, 'c', NULL, NULL, NULL),
  (2022, 152, 'Al aumentar la fuerza iónica de una disolución donde se encuentran iones Ca2+ y Ag+, la variación del coeficiente de actividad de un ion con respecto al valor de 1 (comportamiento ideal) será:', 'Mayor para el catión Ca2+ que para el catión Ag+.', 'Menor para el catión Ca2+ que para el catión Ag+.', 'Igual para ambos cationes.', 'Al ser ionizaciones naturales, ninguno de los dos mostrará variación respecto al comportamiento ideal.', NULL, 'a', NULL, NULL, NULL),
  (2022, 153, '¿Con cuál de las siguientes volumetrías relacionaría la valoración por desplazamiento?:', 'Ácido-base.', 'Formación de complejos.', 'Oxido-reducción.', 'Precipitación.', NULL, 'b', NULL, NULL, NULL),
  (2022, 154, 'En una valoración yodimétrica empleando triyoduro como reactivo valorante, la estandarización previa de este reactivo se realiza con:', 'Permanganato potásico.', 'Dicromato potásico.', 'Tiosulfato de sodio anhidro.', 'Dióxido de cloro.', NULL, 'c', NULL, NULL, NULL),
  (2022, 155, 'En la validación de un método analítico, el límite de cuantificación del método se calcula a través de la señal xLC, obtenida sumando la señal del blanco XB, y la desviación estándar correspondiente a señales repetidas del blanco empleado σB mediante la fórmula: xLC = XB + nσB. ¿Cuál debe ser el valor de n?:', '1.', '2.', '5.', '10.', NULL, 'd', NULL, NULL, NULL),
  (2022, 156, 'La absorbancia total de una disolución a una longitud de onda dada, es:', 'Independiente del disolvente utilizado.', 'Independiente del pH de la disolución.', 'Igual a la suma de las absorbancias de los componentes individuales en la disolución.', 'Igual a la absorbancia del componente más absorbente.', NULL, 'c', NULL, NULL, NULL),
  (2022, 157, 'En espectrofotometría de absorción atómica, un aumento de la temperatura en el atomizador produce:', 'Un aumento de la sensibilidad porque aumenta la eficacia de la atomización.', 'Una disminución de interferencias porque aumenta el ensanchamiento de las líneas atómicas por efecto Doppler.', 'Un aumento de la sensibilidad porque disminuye la eficacia de la atomización.', 'Un aumento de interferencias porque disminuye el ensanchamiento de las líneas atómicas por efecto Doppler.', NULL, 'a', NULL, NULL, NULL),
  (2022, 158, '¿En qué proceso se basa la técnica analítica de nefelometría?:', 'En la absorción de radiación.', 'En la emisión de radiación.', 'En la dispersión de radiación.', 'En la refracción de radiación.', NULL, 'c', NULL, NULL, NULL),
  (2022, 159, 'La técnica más adecuada para el análisis multielemental es:', 'Espectrometría de emisión atómica con arco y chispa.', 'Espectrometría de emisión atómica en plasma.', 'Espectrometría de absorción atómica en llama.', 'Espectrometría de absorción atómica con horno.', NULL, 'b', NULL, NULL, NULL),
  (2022, 160, 'La fluorescencia es un proceso en el que tiene lugar:', 'Una transición radiante en la que se emite un fotón sin cambio de multiplicidad.', 'Una transición radiante en la que se emite un fotón con cambio de multiplicidad.', 'Una transición no radiante en la que se emite un fotón sin cambio de multiplicidad.', 'Una transición no radiante en la que se emite un fotón sin cambio de multiplicidad.', NULL, 'a', NULL, NULL, NULL),
  (2022, 161, '¿Cuál de los siguientes sistemas de ionización utilizados en espectrometría de masas utiliza iones gaseosos reactivos para lograr la obtención de iones?:', 'Ionización química.', 'Ionización por impacto de electrones.', 'Ionización por bombardeo de átomos rápidos.', 'Ionización/desorción asistida por una matriz.', NULL, 'a', NULL, NULL, NULL),
  (2022, 162, 'La membrana de un electrodo selectivo a iones fluoruro constituida prácticamente en su totalidad por LaF3 es una membrana:', 'De vidrio.', 'Sólida cristalina.', 'Líquida con un ionóforo.', 'Líquida con un intercambiador iónico.', NULL, 'b', NULL, NULL, NULL),
  (2022, 163, 'En la determinación cuantitativa de especies atómicas mediante espectrometría de emisión en plasma ICP, las muestras se introducen en la antorcha de plasma:', 'Como nebulizado o aerosol, tangencialmente y a través del cilindro exterior arrastradas por el flujo del aire.', 'Como nebulizado o aerosol, por el cilindro de cuarzo concéntrico central arrastradas por el flujo del aire.', 'Como nebulizado o aerosol, tangencialmente y a través del cilindro exterior arrastradas por el flujo del argón.', 'Como nebulizado o aerosol, por el cilindro de cuarzo concéntrico central arrastradas por el flujo del argón.', NULL, 'd', NULL, NULL, NULL),
  (2022, 164, 'En un espectro de absorción infrarrojo, el número de onda de un grupo funcional diatómico:', 'Aumenta al disminuir la constante de fuerza del enlace.', 'Aumenta al aumentar la masa reducida.', 'Aumenta al aumentar la constante de fuerza del enlace.', 'Es independiente de la masa reducida.', NULL, 'c', NULL, NULL, NULL),
  (2022, 165, 'El inyector de “bucle” o de válvula de 6 vías es una parte crucial del cromatógrafo de líquidos porque, desde un punto de vista cuantitativo, mejora la:', 'Selectividad de la separación.', 'Sensibilidad de la separación.', 'Resolución de la separación.', 'Reproducibilidad de la separación.', NULL, 'd', NULL, NULL, NULL),
  (2022, 166, 'Las transiciones electrónicas con absortividades molares más pequeñas que producen una banda de absorción en la región del espectro visible son:', 'Orbital 𝜋 - orbital 𝜋 antienlazante (𝜋 -𝜋*).', 'Campo-ligando.', 'Orbital no enlazante - orbital 𝜋 antienlazante (n -𝜋*).', 'Orbital no enlazante - orbital 𝜎 antienlazante (n -𝜎*).', NULL, 'b', NULL, NULL, NULL),
  (2022, 167, 'La primera ley de la termodinámica indica que:', 'Si un cuerpo A se encuentra en equilibrio térmico con un cuerpo B y éste a su vez está en equilibrio térmico con un cuerpo C, A y C se encuentran en equilibrio térmico.', 'No es posible alcanzar el cero absoluto en un número finito de etapas.', 'Un sistema termodinámico puede intercambiar energía con su entorno en forma de trabajo y de calor, y variar de esa forma su energía interna. La relación entre estas tres magnitudes viene dada por el principio de conservación de la energía.', 'Es imposible que un sistema realice un proceso cíclico cuyos únicos efectos sean el flujo de calor hacia el sistema desde una fuente de calor y la realización, por parte del sistema, de una cantidad de trabajo equivalente.', NULL, 'c', NULL, NULL, NULL),
  (2022, 168, 'En una reacción de orden 0 (siendo k la constante de velocidad):', 'La velocidad de la reacción es dependiente de la concentración.', 'La representación de la concentración frente al tiempo da una línea recta cuya pendiente es -1/k.', 'El tiempo de semivida es proporcional a la concentración e inversamente proporcional a k.', 'La unidad de la constante k es (t-1).', NULL, 'c', NULL, NULL, NULL),
