-- INSERT preguntas FIR 2022 (convocatoria FSE 2022, Farmacia)
-- Fuente: Cuaderno_2022_F_0_C.pdf + respuestas_2022.xlsx
-- Generado: 210 preguntas validas de 210 impresas (0 anuladas)
-- Pregunta 143 depende de una imagen no incluida en el
-- material recibido: se carga con explicacion_calidad='sin_imagen', imagen_path NULL.
-- tema queda NULL: se clasificara en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2022) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2022 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

